#include <map>

class entity;

class entity_id
{
public:
  bool operator<(const entity_id& e) const { return val < e.val; }

private:
  unsigned int val;
};

typedef map<entity_id, entity*, less<entity_id>, malloc_alloc> entity_map;

pair<entity_map::iterator, bool>
instantiate_insert_unique(entity_map& entities, const entity_map::value_type& value)
{
  return entities.insert(value);
}
